struct SoundScriptManager;
extern SoundScriptManager *sound_manager;
extern "C" int play(SoundScriptManager *, int, void *, float) __asm__("playEvent__18SoundScriptManager9EventTypeP6entityf");
__asm__(".equ sound_manager, 0x0046B4A0");
__asm__(".equ playEvent__18SoundScriptManager9EventTypeP6entityf, 0x0031C380");

struct menu_vtable {
    char padding[0xb0];
    short adjustment;
    short padding2;
    void (*OnRight)(void *, int);
};
struct menu {
    char padding[0x74];
    menu_vtable *vtable;
};
struct entry { int entry_num; };

struct quad_vtable {
    char padding[0x18];
    short adjustment;
    short padding2;
    void (*TurnOn)(void *, bool);
};
struct quad {
    char padding[0x194];
    quad_vtable *vtable;
};

struct extras {
    char padding0[0x4c];
    entry *highlighted;
    char padding1[0x10];
    menu *active;
    char padding2[0x134];
    menu *surfers;
    menu *beaches;
    menu *trailers;
    char padding3[0x6c];
    quad *arrows[2][2];
    int arrow_counter;
    int arrow_num;
};

extern "C" void OnRight(extras *self, int c) __asm__("OnRight__14ExtrasFrontEndi");
void OnRight(extras *self, int c)
{
    if (self->active) {
        menu *active = self->active;
        menu_vtable *table = active->vtable;
        table->OnRight((char *)active + table->adjustment, c);
    }

    switch (self->highlighted->entry_num) {
    case 0: {
        play(sound_manager, 26, 0, 0.0f);
        menu *beaches = self->beaches;
        menu_vtable *table = beaches->vtable;
        table->OnRight((char *)beaches + table->adjustment, c);
        break;
    }
    case 1: {
        play(sound_manager, 26, 0, 0.0f);
        menu *surfers = self->surfers;
        menu_vtable *table = surfers->vtable;
        table->OnRight((char *)surfers + table->adjustment, c);
        break;
    }
    case 2: {
        play(sound_manager, 26, 0, 0.0f);
        menu *trailers = self->trailers;
        menu_vtable *table = trailers->vtable;
        table->OnRight((char *)trailers + table->adjustment, c);
        break;
    }
    }

    if (self->highlighted->entry_num <= 2) {
        quad *on = self->arrows[1][1];
        quad_vtable *on_table = on->vtable;
        on_table->TurnOn((char *)on + on_table->adjustment, true);

        quad *off = self->arrows[1][0];
        quad_vtable *off_table = off->vtable;
        off_table->TurnOn((char *)off + off_table->adjustment, false);

        self->arrow_num = 1;
        self->arrow_counter = 3;
    }
}
